    const created = (await resCreate.json()) as QuoteResponse

    // Create line item without discount
    const resAdd = await app.request(`/api/quotes/${created.id}/lines`, {
      method: 'POST',
      body: JSON.stringify({
        lineType: 'part',
        description: 'Item',
        quantity: 1,
        unitPriceNet: 10000,
        vatRateId: 'vat-standard',
      }),
      headers: { 'Content-Type': 'application/json' },
    })
    const added = (await resAdd.json()) as QuoteLineItemResponse

    // Add 25% discount (2500 basis points)
    const resUpdate = await app.request(`/api/quotes/${created.id}/lines/${added.id}`, {
      method: 'PATCH',
      body: JSON.stringify({
        lineType: 'part',
        discountPercent: 2500,
      }),
      headers: { 'Content-Type': 'application/json' },
    })

    expect(resUpdate.status).toBe(200)

    const json = (await resUpdate.json()) as QuoteLineItemResponse
    expect(json.discountPercent).toBe(2500)
    // lineTotalNet = 10000 * 1 * 0.75 = 7500
    expect(json.lineTotalNet).toBe(7500)
  })

  it('should return 403 when updating a non-draft quote line item', async () => {
    await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({}),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

    // Create line item, then change quote status to 'sent'
    await db.insert(quoteLineItems).values({
      id: 'li1',
      quoteId: created.id,
      lineType: 'part',
      description: 'Item',
      quantity: 1,
      unitPriceNet: 1000,
      vatRateId: 'vat-standard',
      discountPercent: null,
      lineTotalNet: 1000,
      lineTotalVat: 210,
      lineTotalGross: 1210,
    })

    await db.update(quotes).set({ status: 'sent' as const }).where(eq(quotes.id, created.id))

    const resUpdate = await app.request(`/api/quotes/${created.id}/lines/li1`, {
      method: 'PATCH',
      body: JSON.stringify({ lineType: 'part', description: 'Should fail' }),
      headers: { 'Content-Type': 'application/json' },
    })

    expect(resUpdate.status).toBe(403)
  })

  it('should return 404 for non-existent line item', async () => {
    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({}),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

    const resUpdate = await app.request(`/api/quotes/${created.id}/lines/nonexistent`, {
      method: 'PATCH',
      body: JSON.stringify({ lineType: 'part', description: 'Should fail' }),
      headers: { 'Content-Type': 'application/json' },
    })

    expect(resUpdate.status).toBe(404)
  })
})

