describe('DELETE /api/quotes/:quoteId/lines/:lineId', () => {
  it('should delete a line item from a draft quote', async () => {
    await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({}),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

    // Create a line item
    await db.insert(quoteLineItems).values({
      id: 'li1',
      quoteId: created.id,
      lineType: 'part',
      description: 'To delete',
      quantity: 1,
      unitPriceNet: 5000,
      vatRateId: 'vat-standard',
      discountPercent: null,
      lineTotalNet: 5000,
      lineTotalVat: 1050,
      lineTotalGross: 6050,
    })

    const resDelete = await app.request(`/api/quotes/${created.id}/lines/li1`, {
      method: 'DELETE',
    })

    expect(resDelete.status).toBe(200)

    // Verify it's gone
    const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, 'li1'))
    expect(existing).toBeUndefined()
  })

  it('should return 403 when deleting a non-draft quote line item', async () => {
    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({}),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

    // Create line item, then change quote status to 'converted'
    await db.insert(quoteLineItems).values({
      id: 'li1',
      quoteId: created.id,
      lineType: 'part',
      description: 'Item',
      quantity: 1,
      unitPriceNet: 1000,
      vatRateId: 'vat-standard',
      discountPercent: null,
      lineTotalNet: 1000,
      lineTotalVat: 210,
      lineTotalGross: 1210,
    })

    await db.update(quotes).set({ status: 'converted' as const }).where(eq(quotes.id, created.id))

    const resDelete = await app.request(`/api/quotes/${created.id}/lines/li1`, {
      method: 'DELETE',
    })

    expect(resDelete.status).toBe(403)

    const json = (await resDelete.json()) as ErrorResponse
    expect(json.code).toBe('QUOTE_NOT_DRAFT')
  })

  it('should return 404 for non-existent line item', async () => {
    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({}),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

    const resDelete = await app.request(`/api/quotes/${created.id}/lines/nonexistent`, {
      method: 'DELETE',
    })

    expect(resDelete.status).toBe(404)
  })
})

